import React, { useState } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { LogIn } from 'lucide-react';
import toast from 'react-hot-toast';
import './Auth.css';

const LoginForm = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login } = useAuth();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const result = await login(username, password);
      const user = result.user;

      toast.success('Logged in successfully');

      // Role-based redirect
      if (user.role === 'senior_manager') {
        window.location.href = '/senior-manager/dashboard';
      } else if (user.role === 'manager') {
        window.location.href = '/manager/dashboard';
      } else if (user.role === 'planner') {
        window.location.href = '/planner/dashboard';
      } else {
        window.location.href = '/';
      }
    } catch (err) {
      const message = err.message || 'Failed to login';
      setError(message);
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="login-header">
          <p className="login-brand">1Sang Banyuhay Financial Group</p>
          <h1>Coaching Hub</h1>
          <p>Sign in to your account</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="input-group">
            <label>Username</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="e.g., mikko.rodriguez"
              required
              disabled={loading}
            />
          </div>

          <div className="input-group">
            <label>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              required
              disabled={loading}
            />
          </div>

          {error && <div className="error-message">{error}</div>}

          <button type="submit" disabled={loading} className="login-button">
            <LogIn size={20} />
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <div className="login-footer">
          {/* Temporary, for this testing phase only - remove once testing
              is done. */}
          <p className="demo-credentials-label">Demo Credentials (testing only)</p>
          <div className="demo-credentials-list">
            <div className="demo-credentials-row">
              <span className="demo-role">Admin</span>
              <span>admin / DemoAdmin1!</span>
            </div>
            <div className="demo-credentials-row">
              <span className="demo-role">Senior Manager</span>
              <span>demo.seniormanager / DemoSeniorMgr1!</span>
            </div>
            <div className="demo-credentials-row">
              <span className="demo-role">Manager</span>
              <span>demo.manager / DemoManager1!</span>
            </div>
            <div className="demo-credentials-row">
              <span className="demo-role">Planner</span>
              <span>demo.planner / DemoPlanner1!</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginForm;
